import { Menu, Search, Bell, RefreshCw, Sun, Moon } from "lucide-react";
import { useLocation } from "react-router-dom";
import { useAdminTheme } from "../ThemeContext";

const titles = {
  "/admin": "Overview Dashboard",
  "/admin/users": "Users Management",
  "/admin/roles": "Roles & Permissions",
  "/admin/services": "Services Management",
  "/admin/projects": "Company Projects",
  "/admin/products": "Products & Inventory",
  "/admin/orders": "Orders & Sales",
  "/admin/courses": "Courses & Training",
  "/admin/enrollments": "Student Enrollments",
  "/admin/careers": "Job Openings",
  "/admin/applications": "Job Applications",
  "/admin/blog": "Blog & Articles",
  "/admin/testimonials": "Client Testimonials",
  "/admin/partners": "Partners & Collaborators",
  "/admin/subscribers": "Newsletter Subscribers",
  "/admin/contacts": "Contact Inquiries",
  "/admin/analytics": "Analytics & Reports",
  "/admin/activity-logs": "Audit Activity Logs",
  "/admin/settings": "System Settings",
};

export default function AdminHeader({ onMenuClick }) {
  const location = useLocation();
  const { isDark, toggleTheme } = useAdminTheme();
  const title = titles[location.pathname] || "Admin Console";

  return (
    <header
      className={`sticky top-0 z-30 border-b transition-colors duration-200 ${
        isDark
          ? "bg-[#0a0f1e]/90 border-white/5 shadow-sm shadow-purple-950/20 backdrop-blur-md"
          : "bg-white/95 border-slate-200 shadow-sm backdrop-blur-md"
      }`}
    >
      <div className="flex h-14 items-center gap-3 px-4 sm:px-5">

        {/* Mobile menu toggle */}
        <button
          onClick={onMenuClick}
          className={`flex h-8 w-8 items-center justify-center rounded-lg border transition-colors lg:hidden ${
            isDark ? "border-white/10 text-slate-400 hover:bg-white/5" : "border-slate-200 text-slate-600 hover:bg-slate-100"
          }`}
        >
          <Menu size={16} />
        </button>

        {/* Page Title */}
        <div>
          <h1 className={`text-sm font-extrabold tracking-tight ${isDark ? "text-white" : "text-slate-900"}`}>
            {title}
          </h1>
        </div>

        {/* Search */}
        <div className="relative flex-1 max-w-xs ml-4 hidden md:block">
          <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            placeholder="Quick search..."
            className={`w-full rounded-lg border py-1.5 pl-8 pr-3 text-xs outline-none transition ${
              isDark
                ? "border-white/10 bg-white/5 text-slate-200 placeholder-slate-500 focus:border-purple-500"
                : "border-slate-200 bg-slate-50 text-slate-800 placeholder-slate-400 focus:border-purple-500 focus:bg-white"
            }`}
          />
        </div>

        <div className="ml-auto flex items-center gap-2">

          {/* Theme Toggle Button */}
          <button
            onClick={toggleTheme}
            className={`flex h-8 w-8 items-center justify-center rounded-lg border transition-colors ${
              isDark
                ? "border-white/10 text-amber-400 hover:bg-white/5"
                : "border-slate-200 text-slate-600 hover:bg-slate-100"
            }`}
            title={isDark ? "Switch to Light Mode" : "Switch to Dark Mode"}
          >
            {isDark ? <Sun size={15} /> : <Moon size={15} />}
          </button>

          {/* Refresh button */}
          <button
            onClick={() => window.location.reload()}
            className={`flex h-8 w-8 items-center justify-center rounded-lg border transition-colors ${
              isDark ? "border-white/10 text-slate-400 hover:bg-white/5" : "border-slate-200 text-slate-600 hover:bg-slate-100"
            }`}
            title="Refresh"
          >
            <RefreshCw size={13} />
          </button>

          {/* Divider */}
          <div className={`h-4 w-px mx-0.5 ${isDark ? "bg-white/10" : "bg-slate-200"}`} />

          {/* Live System indicator */}
          <div className="flex items-center gap-1.5 rounded-lg border border-emerald-500/20 bg-emerald-500/10 px-2.5 py-1">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
            <span className="text-[11px] font-bold text-emerald-600">Online</span>
          </div>

        </div>
      </div>
    </header>
  );
}

import api from '../../Utils/api';
import { clearSession } from '../../Utils/session';
import { getUser } from '../../Utils/session';
import { NavLink, useNavigate } from "react-router-dom";
import {
  LayoutDashboard, Users, ShieldCheck, Briefcase, FolderKanban,
  ShoppingBag, Package, ShoppingCart, GraduationCap, BookOpen,
  ClipboardList, FileText, MessageSquare, Handshake, Mail, Phone,
  Newspaper, BarChart2, ScrollText, Settings, Wrench, X, LogOut,
  ChevronRight,
} from "lucide-react";
import logo from "../../assets/CODERWANDA.png";
import { useAdminTheme } from "../ThemeContext";

const NAV = [
  { section: null, items: [{ label: "Dashboard", to: "/admin", icon: LayoutDashboard, end: true }] },
  {
    section: "MANAGE",
    items: [
      { label: "Users", to: "/admin/users", icon: Users },
      { label: "Roles", to: "/admin/roles", icon: ShieldCheck },
      { label: "Services", to: "/admin/services", icon: Wrench },
      { label: "Projects", to: "/admin/projects", icon: FolderKanban },
    ],
  },
  {
    section: "ECOMMERCE",
    items: [
      { label: "Products", to: "/admin/products", icon: Package },
      { label: "Orders", to: "/admin/orders", icon: ShoppingCart },
    ],
  },
  {
    section: "TRAINING",
    items: [
      { label: "Courses", to: "/admin/courses", icon: BookOpen },
      { label: "Enrollments", to: "/admin/enrollments", icon: ClipboardList },
    ],
  },
  {
    section: "CAREERS",
    items: [
      { label: "Job Listings", to: "/admin/careers", icon: Briefcase },
      { label: "Applications", to: "/admin/applications", icon: FileText },
    ],
  },
  {
    section: "CONTENT",
    items: [
      { label: "Blog Posts", to: "/admin/blog", icon: Newspaper },
      { label: "Testimonials", to: "/admin/testimonials", icon: MessageSquare },
      { label: "Partners", to: "/admin/partners", icon: Handshake },
      { label: "Subscribers", to: "/admin/subscribers", icon: Mail },
      { label: "Contacts", to: "/admin/contacts", icon: Phone },
    ],
  },
  {
    section: "SYSTEM",
    items: [
      { label: "Analytics", to: "/admin/analytics", icon: BarChart2 },
      { label: "Activity Logs", to: "/admin/activity-logs", icon: ScrollText },
      { label: "Settings", to: "/admin/settings", icon: Settings },
    ],
  },
];

export default function AdminSidebar({ mobileOpen, setMobileOpen }) {
  const navigate = useNavigate();
  const { isDark } = useAdminTheme();
  const user = (getUser() || {});

  const handleLogout = async () => {
    try { await api.post('/auth/logout'); } finally { clearSession(); }
    navigate("/login");
  };

  return (
    <>
      {mobileOpen && (
        <div
          onClick={() => setMobileOpen(false)}
          className="fixed inset-0 z-40 bg-slate-900/40 backdrop-blur-sm lg:hidden"
        />
      )}

      <aside
        className={`fixed inset-y-0 left-0 z-50 flex w-[260px] flex-col transition-all duration-300 lg:translate-x-0 ${
          mobileOpen ? "translate-x-0" : "-translate-x-full"
        } ${
          isDark
            ? "bg-[#0a0f1e] border-r border-white/5 text-slate-200"
            : "bg-white border-r border-slate-200 text-slate-800 shadow-sm"
        }`}
      >
        {/* Top accent line */}
        <div className="h-1 w-full bg-gradient-to-r from-purple-600 via-indigo-500 to-purple-400" />

        {/* Logo & Header */}
        <div
          className={`flex items-center justify-between px-5 py-3.5 border-b ${
            isDark ? "border-white/5" : "border-slate-100"
          }`}
        >
          <div className="flex items-center gap-2.5">
            <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-purple-600 shadow-md shadow-purple-200 text-white font-bold p-1">
              <img src={logo} alt="CodeRwanda" className="h-6 w-auto object-contain brightness-0 invert" />
            </div>
            <div>
              <p className={`text-sm font-extrabold tracking-tight ${isDark ? "text-white" : "text-slate-900"}`}>
                Coder<span className="text-purple-600">wanda</span>
              </p>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Admin Workspace</p>
            </div>
          </div>
          <button
            onClick={() => setMobileOpen(false)}
            className={`rounded-lg p-1.5 lg:hidden ${
              isDark ? "text-slate-400 hover:bg-white/5" : "text-slate-500 hover:bg-slate-100"
            }`}
          >
            <X size={16} />
          </button>
        </div>

        {/* Navigation Items */}
        <nav className="flex-1 overflow-y-auto px-3 py-3 space-y-4 text-xs font-semibold scrollbar-thin">
          {NAV.map((group, gi) => (
            <div key={gi}>
              {group.section && (
                <p className={`mb-1 px-3 text-[10px] font-bold tracking-widest ${isDark ? "text-slate-500" : "text-slate-400"}`}>
                  {group.section}
                </p>
              )}
              <div className="space-y-0.5">
                {group.items.map((item) => {
                  const Icon = item.icon;
                  return (
                    <NavLink
                      key={item.to}
                      to={item.to}
                      end={item.end}
                      onClick={() => setMobileOpen(false)}
                      className={({ isActive }) =>
                        `group flex items-center gap-2.5 rounded-xl px-3 py-2 text-xs font-semibold transition-all ${
                          isActive
                            ? isDark
                              ? "bg-purple-600/20 text-purple-300 border border-purple-500/30"
                              : "bg-purple-50 text-purple-700 border border-purple-200/80 shadow-sm"
                            : isDark
                            ? "text-slate-400 hover:bg-white/5 hover:text-slate-200 border border-transparent"
                            : "text-slate-600 hover:bg-slate-50 hover:text-slate-900 border border-transparent"
                        }`
                      }
                    >
                      {({ isActive }) => (
                        <>
                          <Icon
                            size={15}
                            strokeWidth={isActive ? 2.2 : 1.8}
                            className={isActive ? (isDark ? "text-purple-400" : "text-purple-600") : "text-slate-400 group-hover:text-slate-600"}
                          />
                          <span className="flex-1">{item.label}</span>
                          {isActive && <ChevronRight size={12} className={isDark ? "text-purple-400" : "text-purple-600"} />}
                        </>
                      )}
                    </NavLink>
                  );
                })}
              </div>
            </div>
          ))}
        </nav>

        {/* User Footer */}
        <div className={`border-t p-3 ${isDark ? "border-white/5" : "border-slate-100 bg-slate-50/50"}`}>
          <div className={`flex items-center gap-2.5 rounded-xl p-2.5 border ${isDark ? "bg-white/5 border-white/5" : "bg-white border-slate-200 shadow-sm"}`}>
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-purple-600 to-indigo-600 text-xs font-bold text-white shadow-sm">
              {user.name?.[0]?.toUpperCase() || "A"}
            </div>
            <div className="min-w-0 flex-1">
              <p className={`truncate text-xs font-bold ${isDark ? "text-white" : "text-slate-900"}`}>{user.name || "Admin"}</p>
              <p className="truncate text-[10px] text-slate-400 capitalize">{user.role || "Administrator"}</p>
            </div>
            <button
              onClick={handleLogout}
              title="Logout"
              className="rounded-lg p-1.5 text-slate-400 hover:bg-rose-50 hover:text-rose-600 transition-colors"
            >
              <LogOut size={14} />
            </button>
          </div>
        </div>
      </aside>
    </>
  );
}

import { getUser } from '../../Utils/session';
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import {
  Users, ShoppingCart, GraduationCap, DollarSign,
  Package, BookOpen, Phone, CheckCircle2, Server,
  Database, HardDrive, Shield, FileSpreadsheet,
} from "lucide-react";
import StatCard from "../Components/StatCard";
import RecentUsers from "../Components/RecentUsers";
import RecentActivity from "../Components/RecentActivity";
import QuickActions from "../Components/QuickActions";
import api from "../../Utils/api";
import { useAdminTheme } from "../ThemeContext";

const DEFAULT_BAR_DATA = [28, 42, 35, 58, 47, 63, 52, 71, 65, 80, 74, 91, 83, 96, 88, 100, 92, 78, 85, 94];

export default function AdminDashboard() {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [health, setHealth] = useState({ api: "Online", db: "Online" });
  const { isDark } = useAdminTheme();
  const user = (getUser() || {});

  useEffect(() => {
    api.get("/admin/stats")
      .then((r) => setStats(r.data))
      .catch(() => {})
      .finally(() => setLoading(false));

    api.get("/health")
      .then((r) => {
        setHealth({
          api: r.data?.status === "ok" ? "Online" : "Degraded",
          db: r.data?.database === "connected" ? "Online" : "Disconnected",
        });
      })
      .catch(() => {
        setHealth({ api: "Offline", db: "Unknown" });
      });
  }, []);

  const fmt = (n) => Number(n || 0).toLocaleString();
  const fmtMoney = (n) => `$${Number(n || 0).toLocaleString("en", { minimumFractionDigits: 0 })}`;
  const chartData = stats?.trend && stats.trend.length > 0 ? stats.trend : DEFAULT_BAR_DATA;

  return (
    <div className="space-y-3">

      {/* Header bar - Compact */}
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className={`text-lg font-black tracking-tight ${isDark ? "text-white" : "text-slate-900"}`}>
            Welcome back, {user.name?.split(" ")[0] || "Admin"} 👋
          </h1>
          <p className="text-xs text-slate-500">Platform activity & performance overview</p>
        </div>
        <div className="flex items-center gap-2">
          <Link
            to="/admin/analytics"
            className="flex items-center gap-1.5 rounded-lg bg-purple-600 px-3 py-1.5 text-xs font-bold text-white shadow-sm hover:bg-purple-500 transition-colors"
          >
            <FileSpreadsheet size={13} />
            Generate Report
          </Link>
          <div className="flex items-center gap-1.5 rounded-lg border border-emerald-500/20 bg-emerald-500/10 px-2.5 py-1">
            <CheckCircle2 size={13} className="text-emerald-500" />
            <span className="text-[11px] font-bold text-emerald-600">All Systems Operational</span>
          </div>
        </div>
      </div>

      {/* KPI Grid - Short & Compact (6 cards in a single row on desktop) */}
      <div className="grid gap-2.5 grid-cols-2 sm:grid-cols-3 lg:grid-cols-6">
        <StatCard
          title="Total Users"
          value={fmt(stats?.users)}
          change="+12%"
          positive
          icon={Users}
          color="purple"
          loading={loading}
        />
        <StatCard
          title="Total Orders"
          value={fmt(stats?.orders)}
          change="+8%"
          positive
          icon={ShoppingCart}
          color="blue"
          loading={loading}
        />
        <StatCard
          title="Enrollments"
          value={fmt(stats?.enrollments)}
          change="+18%"
          positive
          icon={GraduationCap}
          color="emerald"
          loading={loading}
        />
        <StatCard
          title="Revenue"
          value={fmtMoney(stats?.revenue)}
          change="+5%"
          positive
          icon={DollarSign}
          color="amber"
          loading={loading}
        />
        <StatCard
          title="Products"
          value={fmt(stats?.products)}
          icon={Package}
          color="blue"
          loading={loading}
        />
        <StatCard
          title="Inquiries"
          value={fmt(stats?.contacts)}
          icon={Phone}
          color="rose"
          loading={loading}
        />
      </div>

      {/* Middle Row: Trend Chart (60%) + Activity Feed (40%) */}
      <div className="grid gap-3 lg:grid-cols-[1.5fr_1fr]">

        {/* Compact Chart */}
        <div
          className={`rounded-xl border p-3.5 transition-colors ${
            isDark ? "border-white/5 bg-[#0d1530]" : "border-slate-200 bg-white shadow-sm"
          }`}
        >
          <div className="flex items-center justify-between mb-2">
            <div>
              <h2 className={`text-xs font-bold ${isDark ? "text-white" : "text-slate-900"}`}>Platform Activity Trend</h2>
              <p className="text-[10px] text-slate-400">Events over the last 20 days</p>
            </div>
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-1.5 text-[10px] text-slate-400">
                <span className="h-2 w-2 rounded-full bg-purple-600" />
                <span>Peak Load</span>
              </div>
              <div className="flex items-center gap-1.5 text-[10px] text-slate-400">
                <span className="h-2 w-2 rounded-full bg-purple-300" />
                <span>Normal</span>
              </div>
            </div>
          </div>

          {/* Bar chart container */}
          <div className="relative h-[110px]">
            {/* Grid lines */}
            <div className="absolute inset-0 flex flex-col justify-between pb-4">
              {[0, 1, 2].map((i) => (
                <div key={i} className={`border-t ${isDark ? "border-white/5" : "border-slate-100"}`} />
              ))}
            </div>

            {/* Bars */}
            <div className="absolute inset-x-0 bottom-4 top-0 flex items-end gap-1 px-1">
              {chartData.map((h, i) => (
                <div key={i} className="group relative flex-1 flex flex-col items-center justify-end h-full">
                  <div
                    className="w-full rounded-t transition-all duration-200"
                    style={{
                      height: `${h}%`,
                      background: h > 80
                        ? "linear-gradient(180deg, #9333ea 0%, #7c3aed 100%)"
                        : isDark
                        ? "linear-gradient(180deg, #4c1d95 0%, #2e1065 100%)"
                        : "linear-gradient(180deg, #c084fc 0%, #a855f7 100%)",
                      opacity: 0.9,
                    }}
                  />
                  {/* Tooltip */}
                  <div className="absolute -top-6 left-1/2 -translate-x-1/2 hidden group-hover:block bg-slate-900 text-white rounded px-1.5 py-0.5 text-[9px] font-bold whitespace-nowrap z-10 shadow">
                    {h}%
                  </div>
                </div>
              ))}
            </div>

            {/* X labels */}
            <div className="absolute bottom-0 left-1 right-1 flex justify-between text-[9px] text-slate-400">
              <span>Day 1</span>
              <span>Day 5</span>
              <span>Day 10</span>
              <span>Day 15</span>
              <span>Day 20</span>
            </div>
          </div>
        </div>

        {/* Recent Activity */}
        <RecentActivity />
      </div>

      {/* Bottom Row: Recent Users (35%) + Quick Shortcuts (35%) + System Health (30%) */}
      <div className="grid gap-3 lg:grid-cols-[1.1fr_1.1fr_0.8fr]">
        <RecentUsers />
        <QuickActions />

        {/* System Health Card */}
        <div
          className={`rounded-xl border p-3.5 transition-colors ${
            isDark ? "border-white/5 bg-[#0d1530]" : "border-slate-200 bg-white shadow-sm"
          }`}
        >
          <div className="flex items-center justify-between mb-2">
            <div>
              <h2 className={`text-xs font-bold ${isDark ? "text-white" : "text-slate-900"}`}>System Health</h2>
              <p className="text-[10px] text-slate-400">Infrastructure operational status</p>
            </div>
            <span className="text-xs font-black text-emerald-600">99.9% uptime</span>
          </div>

          <div className="grid grid-cols-2 gap-2 mt-2">
            {[
              { name: "API Server", status: health.api, icon: Server, color: health.api === "Online" ? "emerald" : "amber" },
              { name: "MySQL DB", status: health.db, icon: Database, color: health.db === "Online" ? "emerald" : "rose" },
              { name: "Storage", status: "Healthy", icon: HardDrive, color: "emerald" },
              { name: "Security", status: "Protected", icon: Shield, color: "emerald" },
            ].map((s) => {
              const Icon = s.icon;
              const isOk = s.color === "emerald";
              return (
                <div
                  key={s.name}
                  className={`flex items-center gap-2 rounded-lg border p-2 ${
                    isDark
                      ? "border-white/5 bg-white/2"
                      : "border-slate-100 bg-slate-50/70"
                  }`}
                >
                  <div className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-md ${
                    isOk
                      ? isDark ? "bg-emerald-500/10 text-emerald-400" : "bg-emerald-50 text-emerald-600"
                      : isDark ? "bg-rose-500/10 text-rose-400" : "bg-rose-50 text-rose-600"
                  }`}>
                    <Icon size={12} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className={`text-[11px] font-bold truncate ${isDark ? "text-white" : "text-slate-800"}`}>{s.name}</p>
                    <p className={`text-[10px] font-semibold ${isOk ? "text-emerald-600" : "text-rose-500"}`}>{s.status}</p>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

    </div>
  );
}

import { downloadReport } from './Manage';
import { useEffect, useState } from "react";
import {
  BarChart2, TrendingUp, Users, ShoppingCart, GraduationCap,
  DollarSign, FileSpreadsheet, Download, Printer, Briefcase,
  Mail, Package, Calendar, RefreshCw, CheckCircle2,
} from "lucide-react";
import api from "../../Utils/api";
import { useAdminTheme } from "../ThemeContext";

export default function AnalyticsPage() {
  const [reportData, setReportData] = useState(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [selectedModule, setSelectedModule] = useState("orders");
  const { isDark } = useAdminTheme();

  const fetchSummary = () => {
    api.get("/admin/reports/summary")
      .then((r) => setReportData(r.data))
      .catch(() => setError('Unable to load analytics. Please retry.'))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchSummary();
  }, []);

  const handleExportCSV = (type) => { downloadReport(type || selectedModule).catch(() => setError('Export failed. Please try again.')); };


  const handlePrint = () => {
    window.print();
  };

  const kpi = reportData?.kpi || {
    users: 0,
    orders: 0,
    enrollments: 0,
    applications: 0,
    contacts: 0,
    revenue: 0,
  };

  return (
    <div className="space-y-4">{error && <p role="alert" className="text-red-500">{error}</p>}

      {/* Header */}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className={`text-lg font-black tracking-tight ${isDark ? "text-white" : "text-slate-900"}`}>
            Analytics & Business Reporting
          </h1>
          <p className="text-xs text-slate-500">
            Real-time platform insights, KPI metrics, and exportable business reports
          </p>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={fetchSummary}
            className={`flex items-center gap-1.5 rounded-lg border px-3 py-1.5 text-xs font-bold transition-colors ${
              isDark
                ? "border-white/10 bg-white/5 text-slate-300 hover:bg-white/10"
                : "border-slate-200 bg-white text-slate-700 hover:bg-slate-50 shadow-sm"
            }`}
          >
            <RefreshCw size={13} className={loading ? "animate-spin" : ""} /> Refresh
          </button>
