import useRemote from '../Utils/useRemote';
import DataState from '../Components/DataState';
import { useEffect, useMemo, useState } from "react";
import api from "../Utils/api";

import { Link, useNavigate } from "react-router-dom";

import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import bgImage from "../assets/bgImage.png";

/* =========================================================
   CATEGORIES
========================================================= */

const formatRWF = (amount) =>
    `${new Intl.NumberFormat("en-RW").format(amount)} RWF`;


const getStoredCart = () => {
    try {
        const stored = localStorage.getItem("coderwanda_cart");

        if (!stored) {
            return [];
        }

        const parsed = JSON.parse(stored);

        return Array.isArray(parsed) ? parsed : [];
    } catch {
        return [];
    }
};


/* =========================================================
   E-COMMERCE
========================================================= */

export default function Ecommerce() {

    const navigate = useNavigate();

    const remote = useRemote('/products');
    const productList = useMemo(() => remote.data.map(item => ({ ...item, oldPrice: item.old_price })), [remote.data]);
    const categories = Array.from(new Set(productList.map(item => item.category))).map(name => ({ name, count: productList.filter(item => item.category === name).length, icon: 'fa-solid fa-box', image: productList.find(item => item.category === name)?.image }));

    const [, setCart] = useState(getStoredCart);

    const [favorites, setFavorites] = useState([]);

    const [activeCategory, setActiveCategory] =
        useState("All");

    const [activeTab, setActiveTab] =
        useState("All Products");

    const [search, setSearch] =
        useState("");

    const [sort, setSort] =
        useState("newest");

    const [visibleProducts, setVisibleProducts] =
        useState(10);

    const [toast, setToast] =
        useState(null);

    /* =====================================================
       FETCH PRODUCTS FROM API
    ===================================================== */





    /* =====================================================
       TOAST
    ===================================================== */

    const showToast = (
        message,
        type = "success"
    ) => {

        setToast({
            message,
            type,
        });

        window.setTimeout(() => {
            setToast(null);
        }, 2800);
    };


    /* =====================================================
       SAVE CART
    ===================================================== */

    const saveCart = (updatedCart) => {

        setCart(updatedCart);

        localStorage.setItem(
            "coderwanda_cart",
            JSON.stringify(updatedCart)
        );

        /*
          IMPORTANT:
          Navbar listens for this event.
        */

        window.dispatchEvent(
            new Event("cartUpdated")
        );
    };


    /* =====================================================
       ADD TO CART
    ===================================================== */

    const handleAddToCart = (product) => {

        /*
          Customer must login before shopping.
        */

        const user =
            localStorage.getItem("coderwanda_user");

        if (!user) {

            /*
              Remember product.
              Login page can process this after
              successful authentication.
            */

            localStorage.setItem(
                "pending_cart_product",
                JSON.stringify(product)
            );

            showToast(
                "Please login to add this product to your cart.",
                "login"
            );

            window.setTimeout(() => {
                navigate("/login", {
                    state: {
                        from: "/ecommerce",
                        productId: product.id,
                    },
                });
            }, 500);

            return;
        }


        const currentCart =
            getStoredCart();


        const existingProduct =
            currentCart.find(
                (item) =>
                    item.id === product.id
            );


        let updatedCart;


        if (existingProduct) {

            updatedCart =
                currentCart.map(
                    (item) =>
                        item.id === product.id
                            ? {
                                ...item,
                                quantity:
                                    Number(
                                        item.quantity || 1
                                    ) + 1,
                            }
                            : item
                );

            showToast(
                `${product.name} quantity increased.`
            );

        } else {

            updatedCart = [
                ...currentCart,
                {
                    ...product,
                    quantity: 1,
                },
            ];

            showToast(
                `${product.name} added to your cart.`
            );
        }


        saveCart(updatedCart);
    };


    /* =====================================================
       FAVORITES
    ===================================================== */

    const toggleFavorite = (id) => {

        setFavorites((current) =>
            current.includes(id)
                ? current.filter(
                    (item) => item !== id
                )
                : [...current, id]
        );
    };


    /* =====================================================
       FILTER PRODUCTS
    ===================================================== */

    const filteredProducts = useMemo(() => {

        let result = [...productList];


        /* CATEGORY */

        if (activeCategory !== "All") {

            result =
                result.filter(
                    (product) =>
                        product.category ===
                        activeCategory
                );
        }


        /* SEARCH */

        const query =
            search.trim().toLowerCase();

        if (query) {

            result =
                result.filter((product) => {

                    return (
                        product.name
                            .toLowerCase()
                            .includes(query) ||

                        product.brand
                            .toLowerCase()
                            .includes(query) ||

                        product.category
                            .toLowerCase()
                            .includes(query)
                    );
                });
        }


        /* TABS */

        if (activeTab === "New Arrivals") {

            result =
                result.filter(
                    (product) =>
                        product.badge === "New"
                );
        }


        if (activeTab === "Best Sellers") {
            result = [...result].sort((a, b) => b.reviews - a.reviews);
        }

        if (activeTab === "Special Offers") {
            result = result.filter((product) => product.oldPrice);
        }

        if (activeTab === "Featured") {
            result = result.filter((product) => product.rating >= 5);
        }


        /* SORT */

        if (sort === "price-low") {
            result = [...result].sort((a, b) => a.price - b.price);
        }

        if (sort === "price-high") {
            result = [...result].sort((a, b) => b.price - a.price);
        }

        if (sort === "rating") {
            result = [...result].sort((a, b) => b.rating - a.rating);
        }


        return result;

    }, [
        productList,
        activeCategory,
        activeTab,
        search,
        sort,
    ]);


    const displayedProducts =
        filteredProducts.slice(
            0,
            visibleProducts
        );


    /* =====================================================
       RESET
    ===================================================== */

    const resetFilters = () => {

        setActiveCategory("All");

        setActiveTab("All Products");

        setSearch("");

        setSort("newest");

        setVisibleProducts(10);
    };


    /* =====================================================
       CATEGORY
    ===================================================== */

    const handleCategory = (category) => {

        setActiveCategory(category);

        setActiveTab("All Products");

        setVisibleProducts(10);

        window.setTimeout(() => {

            document
                .getElementById("products")
                ?.scrollIntoView({
                    behavior: "smooth",
                });

        }, 50);
    };


    /* =====================================================
       SHOP NOW
    ===================================================== */

    const scrollToProducts = () => {

        document
            .getElementById("products")
            ?.scrollIntoView({
                behavior: "smooth",
            });
    };


    /* =====================================================
       RENDER
    ===================================================== */

    return (

        <main className="min-h-screen bg-white text-slate-900">

            <Navbar />
            <DataState {...remote} empty={!remote.data.length} label="products" />


            {/* =================================================
                TOAST
            ================================================= */}

            {toast && (

                <div
                    className="
                        fixed
                        right-4
                        top-24
                        z-[100]
                        w-[calc(100%-2rem)]
                        max-w-sm
                    "
                >

                    <div
                        className="
                            flex
                            items-start
                            gap-3
                            rounded-2xl
                            border
                            border-slate-200
                            bg-white
                            p-4
                            shadow-2xl
                        "
                    >

                        <div
                            className={`
                                flex
                                h-10
                                w-10
                                shrink-0
                                items-center
                                justify-center
                                rounded-full
                                ${toast.type === "login"
                                    ? "bg-amber-100 text-amber-600"
                                    : "bg-purple-100 text-purple-700"
                                }
                            `}
                        >

                            <i
                                className={
                                    toast.type === "login"
                                        ? "fa-solid fa-lock"
                                        : "fa-solid fa-check"
                                }
                            />

                        </div>


                        <div className="flex-1">

                            <p className="text-sm font-bold text-slate-900">

                                {toast.type === "login"
                                    ? "Login required"
                                    : "Cart updated"}

                            </p>

                            <p className="mt-1 text-xs leading-5 text-slate-500">
                                {toast.message}
                            </p>

                        </div>


                        <button
                            type="button"
                            onClick={() =>
                                setToast(null)
                            }
                            className="
                                text-slate-400
                                transition
                                hover:text-slate-800
                            "
                        >
                            <i className="fa-solid fa-xmark" />
                        </button>

                    </div>

                </div>
            )}


            {/* =================================================
                HERO
            ================================================= */}

            <section
                className="relative overflow-hidden"
                style={{
                    backgroundImage: `url(${bgImage})`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                }}
            >
                {/* Dark overlay */}
                <div className="absolute inset-0 bg-slate-950/50" />

                {/* Purple glow */}
                <div className="pointer-events-none absolute inset-0">
                    <div className="absolute left-1/4 top-0 h-[350px] w-[600px] rounded-full bg-purple-700/25 blur-[120px]" />
                </div>

                <div className="relative mx-auto max-w-7xl px-5 sm:px-8 lg:px-10">
                    <div className="grid items-center gap-10 py-6 sm:py-20 lg:grid-cols-2">

                        {/* LEFT — content */}
                        <div>
                            {/* Eyebrow */}
                            <div className="mb-2 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.06] px-4 py-2 backdrop-blur">
                                <span className="h-1.5 w-1.5 rounded-full bg-fuchsia-400" />
